  'diag.shorted_voltage_source': 'Zkratovaný zdroj napětí ({ids}): oba vývody sdílejí jeden uzel. Oddělte piny.',
  'diag.singular_fallback': 'Obvod nelze vyřešit. Zkontrolujte, že je Zem zapojená a že nejsou žádné plovoucí součástky.',
  'diag.ac_nonlinear_open': 'Nelineární a spínací součástky se v AC berou jako rozpojené ({ids}). Pro LED, diody, tranzistory, relé, motory a piny mikrokontroléru použijte Transient.',
  'diag.ac_source_tran_no_freq': 'Střídavý zdroj potřebuje pro sinus v Transientu Frekvenci (Hz) > 0. Bez ní má zdroj 0 V.',
